'use strict';

const CATEGORIES = {
  carnes: {name:'Carnes', icon:'utensils', color:'#ead8be'},
  aves: {name:'Aves', icon:'utensils', color:'#e9dfb8'},
  pescados: {name:'Pescados y mariscos', icon:'fish', color:'#d9e6d8'},
  arroces: {name:'Arroces', icon:'bowl', color:'#eadcb8'},
  granos_sopas: {name:'Granos y sopas', icon:'bowl', color:'#e1d9c3'},
  viandas_ensaladas: {name:'Viandas y ensaladas', icon:'leaf', color:'#dfe5cc'},
  entrantes: {name:'Entrantes', icon:'utensils', color:'#ecdac8'},
  pasteleria: {name:'Pastelería', icon:'cake', color:'#f0dbca'},
  postres: {name:'Postres', icon:'cake', color:'#eadcc5'},
  bebidas: {name:'Bebidas', icon:'cup', color:'#dce8ce'}
};
